"""Self-contained HTML for verified operational Perfect Store and original cell traces."""
import argparse,base64,gzip,json,copy
from pathlib import Path
import engine,collection_adapter,perfect_store_check

def pack_references(result):
 """Index repeated fingerprints for transport; retain every original identifier."""
 cell_ids=sorted(result['cells']);answer_ids=sorted(result['answer_evidence']);ci={k:i for i,k in enumerate(cell_ids)};ai={k:i for i,k in enumerate(answer_ids)}
 result['cells']=[result['cells'][k] for k in cell_ids]
 result['answer_evidence']=[dict(result['answer_evidence'][k],cell_ids=[ci[c] for c in result['answer_evidence'][k]['cell_ids']]) for k in answer_ids]
 for row in result['details']:
  row['eligibility_evidence']=ai[row['eligibility_evidence']]
  for c in row['components']:c['evidence_ids']=[ai[k] for k in c['evidence_ids']]
 for row in result['explicitly_ineligible']:row['eligibility_evidence']=ai[row['eligibility_evidence']]
 return {'schema':'mindtec-ps-reference-indices/1','cell_fingerprints':cell_ids,'answer_fingerprints':answer_ids,'lossless_reference_indexing':True}

def restore_references(result,transport):
 result=copy.deepcopy(result);cids=transport['cell_fingerprints'];aids=transport['answer_fingerprints'];result['cells']={key:cell for key,cell in zip(cids,result['cells'],strict=True)};result['answer_evidence']={key:dict(a,cell_ids=[cids[i] for i in a['cell_ids']]) for key,a in zip(aids,result['answer_evidence'],strict=True)}
 for row in result['details']:
  row['eligibility_evidence']=aids[row['eligibility_evidence']]
  for c in row['components']:c['evidence_ids']=[aids[i] for i in c['evidence_ids']]
 for row in result['explicitly_ineligible']:row['eligibility_evidence']=aids[row['eligibility_evidence']]
 return result

def export(runtime,output):
 runtime=Path(runtime).resolve();output=Path(output).resolve()
 if output.is_relative_to(runtime):raise ValueError('Report must remain outside audit custody')
 if not (runtime/'audit.sqlite').is_file():raise ValueError('Existing PS custody required')
 with engine.Engine(runtime) as e:
  e.db.execute('BEGIN')
  try:
   head=e.verify();run=e.db.execute("SELECT * FROM runs WHERE json_extract(rules_json,'$.kind')='operational_perfect_store' ORDER BY at DESC,id DESC LIMIT 1").fetchone()
   if not run:raise ValueError('Accepted operational PS result missing')
   def object_bytes(digest):
    row=e.db.execute('SELECT object_path FROM snapshots WHERE hash=?',(digest,)).fetchone()
    if not row:raise ValueError('PS evidence object missing')
    raw=(e.root/row[0]).read_bytes()
    if engine.sha(raw)!=digest:raise ValueError('PS evidence hash differs')
    return raw
   result=engine.load_json_bytes(object_bytes(run['snapshot_hash']));rules=engine.load_json_bytes(run['rules_json'].encode());source=rules['reference_sources']['detailed_workbook'];book=collection_adapter.workbook_tables('retained-detail.xlsx',object_bytes(source))
   checks={**perfect_store_check.verify_model(result),**perfect_store_check.verify_cells(result,book)}
   data={'run_id':run['id'],'snapshot_sha256':run['snapshot_hash'],'ledger_head':head,'generated_at':engine.now(),'policy':engine.load_json_bytes(run['policy_json'].encode()),'reference_sources':rules['reference_sources'],'verification':checks,'result':result}
  finally:e.db.execute('ROLLBACK')
 data['transport']=pack_references(result)
 payload=base64.b64encode(gzip.compress(engine.canonical(data).encode(),mtime=0)).decode()
